#!/usr/bin/env python3
# Generated by morzsa via A2A Mesh delegation
"""
ötletláda: Tudás megőrzése — keresés + alacsony küszöbű tanulság-sablon + reprodukció-jelzés

Ez a modul a mesh tudás-megosztásához nyújt:
  - Kereshető tudásbázis (JSON-alapú, egyszerű szöveges index)
  - Rövid kitölthető sablon (tünet / mit mértél / mi a javítás / hogyan ellenőrizted)
  - "Nálam is működött" reprodukció-jelzés, ami egy tapasztalatot tudássá tesz

A tanult lesson-ok nem vesznek el: kereshetők maradnak és a reprodukciók
megerősítik a megbízhatóságukat.
"""

from __future__ import annotations

import argparse
import json
import os
import re
import sys
import time
import hashlib
from dataclasses import dataclass, asdict, field
from pathlib import Path
from typing import Optional

# ---------------------------------------------------------------------------
# Adatmodell
# ---------------------------------------------------------------------------

@dataclass
class Reproduction:
    """Egy 'nálam is működött' (vagy 'nem működött') jelzés."""
    reproducer: str
    worked: bool
    timestamp: float
    note: str = ""

@dataclass
class Lesson:
    """Egy tanulság a sablon szerint."""
    id: str
    title: str
    symptom: str          # tünet — mi volt a probléma
    measured: str         # mit mértél
    fix: str              # mi a javítás
    verified: str         # hogyan ellenőrizted
    author: str
    tags: list[str] = field(default_factory=list)
    created_at: float = 0.0
    reproductions: list[dict] = field(default_factory=list)

    def to_dict(self) -> dict:
        return asdict(self)

    @classmethod
    def from_dict(cls, d: dict) -> "Lesson":
        return cls(**d)

# ---------------------------------------------------------------------------
# Tudásbázis — perzisztens JSON tároló + egyszerű szöveges keresés
# ---------------------------------------------------------------------------

class KnowledgeBase:
    """Kereshető tudásbázis lesson-ok tárolására és keresésére."""

    def __init__(self, db_path: Path):
        self.db_path = Path(db_path)
        self.lessons: dict[str, Lesson] = {}
        self._load()

    # --- perzisztencia ---

    def _load(self):
        if self.db_path.exists():
            try:
                raw = json.loads(self.db_path.read_text(encoding="utf-8"))
                for lid, ldict in raw.items():
                    self.lessons[lid] = Lesson.from_dict(ldict)
            except (json.JSONDecodeError, TypeError):
                self.lessons = {}

    def _save(self):
        self.db_path.parent.mkdir(parents=True, exist_ok=True)
        data = {lid: lesson.to_dict() for lid, lesson in self.lessons.items()}
        self.db_path.write_text(
            json.dumps(data, indent=2, ensure_ascii=False),
            encoding="utf-8",
        )

    # --- CRUD ---

    @staticmethod
    def _make_id(title: str, author: str) -> str:
        h = hashlib.sha1(f"{title}|{author}|{time.time()}".encode()).hexdigest()[:12]
        return f"lesson_{h}"

    def add_lesson(
        self,
        title: str,
        symptom: str,
        measured: str,
        fix: str,
        verified: str,
        author: str,
        tags: Optional[list[str]] = None,
    ) -> Lesson:
        lid = self._make_id(title, author)
        lesson = Lesson(
            id=lid,
            title=title.strip(),
            symptom=symptom.strip(),
            measured=measured.strip(),
            fix=fix.strip(),
            verified=verified.strip(),
            author=author.strip(),
            tags=tags or [],
            created_at=time.time(),
            reproductions=[],
        )
        self.lessons[lid] = lesson
        self._save()
        return lesson

    def get(self, lesson_id: str) -> Optional[Lesson]:
        return self.lessons.get(lesson_id)

    def all(self) -> list[Lesson]:
        return list(self.lessons.values())

    def delete(self, lesson_id: str) -> bool:
        if lesson_id in self.lessons:
            del self.lessons[lesson_id]
            self._save()
            return True
        return False

    # --- reprodukció ---

    def add_reproduction(
        self,
        lesson_id: str,
        reproducer: str,
        worked: bool,
        note: str = "",
    ) -> bool:
        lesson = self.get(lesson_id)
        if lesson is None:
            return False
        lesson.reproductions.append(
            Reproduction(
                reproducer=reproducer.strip(),
                worked=worked,
                timestamp=time.time(),
                note=note.strip(),
            ).__dict__
        )
        self._save()
        return True

    def reproduction_count(self, lesson_id: str) -> tuple[int, int]:
        """Visszaadja (worked, failed) számát."""
        lesson = self.get(lesson_id)
        if lesson is None:
            return (0, 0)
        worked = sum(1 for r in lesson.reproductions if r["worked"])
        failed = sum(1 for r in lesson.reproductions if not r["worked"])
        return (worked, failed)

    # --- keresés ---

    def search(self, query: str, limit: int = 50) -> list[tuple[Lesson, float]]:
        """
        Egyszerű szöveges keresés: a query szavait a lesson mezőiben keresi.
        Visszatér (lesson, score) párokként, csökkenő pontszám szerint.
        """
        if not query.strip():
            return [(l, 0.0) for l in self.all()][:limit]

        words = [w.lower() for w in re.split(r"\s+", query.strip()) if w]
        results: list[tuple[Lesson, float]] = []

        for lesson in self.lessons.values():
            haystack_parts = [
                lesson.title, lesson.symptom, lesson.measured,
                lesson.fix, lesson.verified, lesson.author,
                " ".join(lesson.tags),
            ]
            haystack = " ".join(haystack_parts).lower()
            score = 0.0
            for w in words:
                count = haystack.count(w)
                score += count
                # cím találat extra súly
                if w in lesson.title.lower():
                    score += 3
                # tag találat extra súly
                if any(w == t.lower() for t in lesson.tags):
                    score += 2
            # reprodukciók megerősítik a relevanciát
            w_count, _ = self.reproduction_count(lesson.id)
            score += w_count * 0.5
            if score > 0:
                results.append((lesson, score))

        results.sort(key=lambda x: x[1], reverse=True)
        return results[:limit]

# ---------------------------------------------------------------------------
# Sablon — alacsony küszöbű, interaktív kitöltés
# ---------------------------------------------------------------------------

LESSON_TEMPLATE = """\
--- Lesson sablon ---
Tünet (mi volt a probléma?):
  {symptom}

Mit mértél?
  {measured}

Mi a javítás?
  {fix}

Hogyan ellenőrizted?
  {verified}
---------------------
"""

def interactive_template(kb: KnowledgeBase, author: str) -> Optional[Lesson]:
    """Interaktív sablon-kitöltés a terminálban — alacsony küszöb."""
    print("\n=== Új tanulság rögzítése (sablon) ===\n")
    title = input("Cím (rövid, 1 sor): ").strip()
    if not title:
        print("Megszakítva: cím kötelező.")
        return None
    symptom = input("Tünet (mi volt a probléma?): ").strip()
    measured = input("Mit mértél?: ").strip()
    fix = input("Mi a javítás?: ").strip()
    verified = input("Hogyan ellenőrizted?: ").strip()
    tags_raw = input("Címkék (szóközzel elválasztva, opcionális): ").strip()
    tags = [t for t in tags_raw.split() if t]

    if not (symptom or measured or fix or verified):
        print("Megszakítva: legalább egy mezőt ki kell tölteni.")
        return None

    lesson = kb.add_lesson(
        title=title,
        symptom=symptom,
        measured=measured,
        fix=fix,
        verified=verified,
        author=author,
        tags=tags,
    )
    print(f"\n✓ Lesson elmentve: {lesson.id}")
    print(LESSON_TEMPLATE.format(
        symptom=lesson.symptom, measured=lesson.measured,
        fix=lesson.fix, verified=lesson.verified,
    ))
    return lesson

# ---------------------------------------------------------------------------
# Megjelenítés
# ---------------------------------------------------------------------------

def format_lesson(lesson: Lesson, kb: KnowledgeBase, verbose: bool = False) -> str:
    worked, failed = kb.reproduction_count(lesson.id)
    repro_line = f"  reprodukció: ✓{worked} ✗{failed}"
    header = f"[{lesson.id}] {lesson.title}  (by {lesson.author})  {repro_line}"
    if not verbose:
        return header
    lines = [header, ""]
    lines.append(f"  Tünet:        {lesson.symptom}")
    lines.append(f"  Mit mértél:   {lesson.measured}")
    lines.append(f"  Javítás:      {lesson.fix}")
    lines.append(f"  Ellenőrzés:   {lesson.verified}")
    if lesson.tags:
        lines.append(f"  Címkék:       {', '.join(lesson.tags)}")
    if lesson.reproductions:
        lines.append("  Reprodukciók:")
        for r in lesson.reproductions:
            mark = "✓" if r["worked"] else "✗"
            ts = time.strftime("%Y-%m-%d %H:%M", time.localtime(r["timestamp"]))
            note = f" — {r['note']}" if r["note"] else ""
            lines.append(f"    {mark} {r['reproducer']} ({ts}){note}")
    return "\n".join(lines)

# ---------------------------------------------------------------------------
# CLI
# ---------------------------------------------------------------------------

DEFAULT_DB = Path("vault") / "knowledge_base.json"

def cmd_add(args, kb: KnowledgeBase):
    interactive_template(kb, args.author)

def cmd_search(args, kb: KnowledgeBase):
    results = kb.search(args.query, limit=args.limit)
    if not results:
        print("Nincs találat.")
        return
    print(f"\n{len(results)} találat:\n")
    for lesson, score in results:
        print(format_lesson(lesson, kb, verbose=args.verbose))
        print(f"  (pontszám: {score:.1f})")
        print()

def cmd_list(args, kb: KnowledgeBase):
    lessons = kb.all()
    if not lessons:
        print("A tudásbázis üres.")
        return
    print(f"\n{len(lessons)} lesson a tudásbázisban:\n")
    for lesson in sorted(lessons, key=lambda l: l.created_at, reverse=True):
        print(format_lesson(lesson, kb, verbose=args.verbose))
        print()

def cmd_reproduce(args, kb: KnowledgeBase):
    lesson = kb.get(args.lesson_id)
    if lesson is None:
        print(f"Nem található lesson: {args.lesson_id}")
        return
    worked = args.verdict in ("yes", "y", "worked", "true", "1")
    ok = kb.add_reproduction(args.lesson_id, args.reproducer, worked, args.note or "")
    if ok:
        mark = "✓ működött" if worked else "✗ nem működött"
        print(f"Reprodukció rögzítve: {mark} by {args.reproducer}")
        w, f_ = kb.reproduction_count(args.lesson_id)
        print(f"Összes reprodukció: ✓{w} ✗{f_}")
        if w >= 2:
            print("★ Ez a lesson elérte a 2+ reprodukciót — tapasztalatból tudássá vált.")
    else:
        print("Hiba: lesson nem található.")

def cmd_show(args, kb: KnowledgeBase):
    lesson = kb.get(args.lesson_id)
    if lesson is None:
        print(f"Nem található lesson: {args.lesson_id}")
        return
    print(format_lesson(lesson, kb, verbose=True))

def cmd_delete(args, kb: KnowledgeBase):
    if kb.delete(args.lesson_id):
        print(f"Lesson törölve: {args.lesson_id}")
    else:
        print(f"Nem található lesson: {args.lesson_id}")

def cmd_export(args, kb: KnowledgeBase):
    """Exportálja az összes lesson-t DREAM.md / vault-barát JSON formátumba."""
    lessons = kb.all()
    export = {
        "source": "knowledge_base",
        "exported_at": time.time(),
        "count": len(lessons),
        "lessons": [l.to_dict() for l in lessons],
    }
    out_path = Path(args.output)
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(json.dumps(export, indent=2, ensure_ascii=False), encoding="utf-8")
    print(f"Exportálva: {out_path} ({len(lessons)} lesson)")

def build_parser() -> argparse.ArgumentParser:
    p = argparse.ArgumentParser(
        prog="knowledge_keeper",
        description="Tudás megőrzése: keresés + sablon + reprodukció-jelzés",
    )
    p.add_argument("--db", type=Path, default=DEFAULT_DB, help="Tudásbázis JSON útvonala")
    sub = p.add_subparsers(dest="command", required=True)

    p_add = sub.add_parser("add", help="Új lesson rögzítése sablon alapján")
    p_add.add_argument("--author", default="anonymous")
    p_add.set_defaults(func=cmd_add)

    p_search = sub.add_parser("search", help="Keresés a tudásbázisban")
    p_search.add_argument("query", help="Keresési kifejezés")
    p_search.add_argument("--limit", type=int, default=50)
    p_search.add_argument("-v", "--verbose", action="store_true")
    p_search.set_defaults(func=cmd_search)

    p_list = sub.add_parser("list", help="Összes lesson listázása")
    p_list.add_argument("-v", "--verbose", action="store_true")
    p_list.set_defaults(func=cmd_list)

    p_repro = sub.add_parser("reproduce", help="Reprodukció-jelzés ('nálam is működött')")
    p_repro.add_argument("lesson_id")
    p_repro.add_argument("--reproducer", default="anonymous")
    p_repro.add_argument("--verdict", default="yes",
                         choices=["yes", "y", "worked", "true", "1", "no", "n", "failed", "false", "0"],
                         help="Működött-e (yes/no)")
    p_repro.add_argument("--note", default="")
    p_repro.set_defaults(func=cmd_reproduce)

    p_show = sub.add_parser("show", help="Egy lesson részletes megjelenítése")
    p_show.add_argument("lesson_id")
    p_show.set_defaults(func=cmd_show)

    p_del = sub.add_parser("delete", help="Lesson törlése")
    p_del.add_argument("lesson_id")
    p_del.set_defaults(func=cmd_delete)

    p_exp = sub.add_parser("export", help="Exportálás JSON-ba (vault/DREAM.md integráció)")
    p_exp.add_argument("--output", default="vault/knowledge_export.json")
    p_exp.set_defaults(func=cmd_export)

    return p

# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------

def main():
    parser = build_parser()
    args = parser.parse_args()
    kb = KnowledgeBase(args.db)
    args.func(args, kb)

if __name__ == "__main__":
    main()